#include <bits/stdc++.h>
using namespace std;struct P{int x,y;};struct Geo{string word;vector<P>in,out,ctx;};
#include "fast_control_geometry.hpp"
using K=uint64_t;K key(P p){return K(uint32_t(p.x))<<32|uint32_t(p.y);}P rot(P p,int h){switch((h%4+4)%4){case 0:return p;case 1:return{p.y,-p.x};case 2:return{-p.x,-p.y};default:return{-p.y,p.x};}}P pos{0,0};int heading=0;P world(P q){P z=rot(q,heading);return{pos.x+z.x,pos.y+z.y};}int linear_rank(P q,int ph){q=rot(q,ph);return 2*(q.x+q.y);}unordered_map<K,char>colors;vector<pair<K,char>>undoC;
bool trace(string const&w){P ds[]={{0,1},{1,0},{0,-1},{-1,0}};for(char c:w){K q=key(pos);auto it=colors.find(q);char old=it==colors.end()?0:it->second;if(old==c)return false;undoC.push_back({q,old});colors[q]=c;heading=(heading+(c=='R'?1:3))%4;pos.x+=ds[heading].x;pos.y+=ds[heading].y;}return true;}void undo(size_t n){while(undoC.size()>n){auto[q,c]=undoC.back();undoC.pop_back();if(c)colors[q]=c;else colors.erase(q);}}
unordered_set<K>produced;vector<pair<K,bool>>undoP;void setp(K q,bool v){bool old=produced.count(q);undoP.push_back({q,old});if(v)produced.insert(q);else produced.erase(q);}void undop(size_t n){while(undoP.size()>n){auto[q,v]=undoP.back();undoP.pop_back();if(v)produced.insert(q);else produced.erase(q);}}
vector<int>path;vector<long long>counts;long long attempts=0;int limit,threshold;long long cap;int A[]={0,22,20,10};int best=-999;bool found=false;struct E{int phase,required,peak,oldcore,qmax;};
void output(E e){cout<<"EVENT {\"phase\":"<<e.phase<<",\"required_I\":"<<e.required<<",\"peak\":"<<e.peak<<",\"earlier_core_peak\":"<<e.oldcore<<",\"maximum_initial_input_rank\":"<<e.qmax<<",\"packet_ids\":[";for(int i=0;i<(int)path.size();i++)cout<<(i?",":"")<<path[i];cout<<"],\"target_index\":"<<path.size()-2<<"}\n";cout.flush();}
void dfs(array<int,4>C,array<int,4>Q,vector<E>pending){if(found||attempts>=cap||int(path.size())==limit)return;for(int a:{0,1,4,5,6,7,8,9}){if(found||attempts>=cap)return;attempts++;size_t cp=undoC.size();P pp=pos;int hh=heading;if(!trace(geometry[a].word)){undo(cp);pos=pp;heading=hh;continue;}size_t cm=undoC.size();P pe=pos;int he=heading;bool good=trace("LLLLRLRRRRL");undo(cm);pos=pe;heading=he;if(!good){undo(cp);pos=pp;heading=hh;continue;}path.push_back(a);counts[path.size()]++;
for(E e:pending)if(e.required>best){best=e.required;output(e);if(best>threshold){found=true;break;}}if(found)return;
array<int,4>NC=C,NQ=Q;pos=pp;heading=hh;for(P z:geometry[a].in){P q=world(z);if(!produced.count(key(q)))for(int ph=0;ph<4;ph++)NQ[ph]=max(NQ[ph],linear_rank(q,ph));}vector<E>next;for(int ph=0;ph<4;ph++){int peak=linear_rank(pe,ph)+A[(he+ph)%4];if(peak>C[ph])next.push_back({ph,peak-NQ[ph],peak,C[ph],NQ[ph]});NC[ph]=max(C[ph],peak);}
size_t lp=undoP.size();for(P z:geometry[a].ctx){K q=key(world(z));if(produced.count(q))setp(q,false);}for(P z:geometry[a].out)setp(key(world(z)),true);pos=pe;heading=he;dfs(NC,NQ,next);undop(lp);path.pop_back();undo(cp);pos=pp;heading=hh;}}
int main(int argc,char**argv){limit=argc>1?atoi(argv[1]):12;threshold=argc>2?atoi(argv[2]):28;cap=argc>3?atoll(argv[3]):200000000;counts.assign(limit+1,0);counts[0]=1;auto t=chrono::steady_clock::now();dfs({0,22,20,10},{-1000000,-1000000,-1000000,-1000000},{});cout<<"SUMMARY {\"depth\":"<<limit<<",\"attempts\":"<<attempts<<",\"max_required_I\":"<<best<<",\"found_exceeding_threshold\":"<<(found?"true":"false")<<",\"capped\":"<<((attempts>=cap)?"true":"false")<<",\"counts\":[";for(int i=0;i<=limit;i++)cout<<(i?",":"")<<counts[i];cout<<"],\"seconds\":"<<chrono::duration<double>(chrono::steady_clock::now()-t).count()<<"}\n";}
